"""An area of the screen to read as video, chosen by dragging a box on a picture of the desktop (or typed): the
Video node's screen and a VJ deck's both take it, as an entry video.area_name() makes.

    screen_area.pick(app, current, on_pick)   # on_pick(name) with "area: x,y wxh" when it is used
"""
# AI: below section was generated by an AI
import dearpygui.dearpygui as dpg
import numpy as np

from native.typeface import px
from native import video

TAG = "screen_area_win"
VIEW_W, VIEW_H = 860, 480                # the desktop's picture at most this big in the window (before px)
_ST = {}                                  # the picture's scale and origin, the box, the drag and who asked


def _c():
    from native import chrome
    return chrome


def grab():
    """The whole desktop as an (h, w, 3) uint8 picture, and its top left in the desktop's pixels; or (None, why)."""
    try:
        from PIL import ImageGrab
        try:
            im = ImageGrab.grab(all_screens=True)
        except TypeError:                                     # a Pillow without all_screens
            im = ImageGrab.grab()
        return np.asarray(im.convert("RGB")), video.desktop_origin()
    except Exception as e:
        return None, f"no picture of the screen here ({e})"


def box_to_area(box, scale, origin):
    """The box dragged on the picture (x0, y0, x1, y1 in its pixels, either way round) as (x, y, w, h) on the
    desktop: scaled up, moved by where the desktop starts, its size even (ffmpeg's frames are)."""
    x0, y0, x1, y1 = box
    l, r = sorted((x0, x1))
    t, b = sorted((y0, y1))
    x, y = int(round(l / scale)) + origin[0], int(round(t / scale)) + origin[1]
    w, h = max(2, int(round((r - l) / scale))) // 2 * 2, max(2, int(round((b - t) / scale))) // 2 * 2
    return x, y, w, h


def area_to_box(area, scale, origin):
    x, y, w, h = area
    l, t = (x - origin[0]) * scale, (y - origin[1]) * scale
    return l, t, l + w * scale, t + h * scale


def pick(app, current, on_pick):
    """The window: the desktop's picture, a box on it to drag (the current area's, when there is one), its numbers
    to type, Use and Cancel."""
    shot, origin = grab()
    if shot is None:
        app.gp.status(origin, "warn"); return
    from native.textures import registry
    h, w = shot.shape[:2]
    scale = min(px(VIEW_W) / w, px(VIEW_H) / h, 1.0)
    vw, vh = max(1, int(w * scale)), max(1, int(h * scale))
    from PIL import Image
    small = np.asarray(Image.fromarray(shot).resize((vw, vh), Image.BILINEAR))
    rgba = np.concatenate([small.astype(np.float32) / 255.0, np.ones((vh, vw, 1), np.float32)], 2).ravel()
    tex = f"screen_area_tex_{dpg.generate_uuid()}"            # a new texture each time: the old may still be drawn
    dpg.add_static_texture(vw, vh, rgba, tag=tex, parent=registry())
    area = video.parse_area(current) or (origin[0] + w // 4, origin[1] + h // 4, w // 2 // 2 * 2, h // 2 // 2 * 2)
    _ST.clear()
    _ST.update(scale=scale, origin=origin, size=(w, h), box=area_to_box(area, scale, origin), drag=None,
               on_pick=on_pick, app=app, tex=tex)
    if dpg.does_item_exist(TAG):
        dpg.delete_item(TAG)
    c = _c()
    with dpg.window(tag=TAG, label="An area of the screen", modal=True, no_collapse=True, width=vw + px(30),
                    height=vh + px(150), on_close=_close):
        dpg.add_text("Drag a box over what to read - a video player, a visualiser, part of a page.", color=c.DIM)
        dpg.add_drawlist(vw, vh, tag="screen_area_draw")
        with dpg.group(horizontal=True):
            for key, label in (("x", "left"), ("y", "top"), ("w", "width"), ("h", "height")):
                dpg.add_text(label, color=c.DIM)
                dpg.add_input_int(tag=f"screen_area_{key}", width=px(80), step=0, on_enter=True,
                                  callback=lambda s, v: _typed())
            c.tip("the area in the desktop's pixels: Enter puts the box there")
        with dpg.group(horizontal=True):
            dpg.add_button(label="Use this area", tag="screen_area_use", callback=_use)
            dpg.add_button(label="Cancel", callback=_close)
            dpg.add_text("", tag="screen_area_words", color=c.DIM)
    with dpg.handler_registry(tag="screen_area_mouse"):
        dpg.add_mouse_click_handler(button=dpg.mvMouseButton_Left, callback=_down)
        dpg.add_mouse_drag_handler(button=dpg.mvMouseButton_Left, callback=_move)
        dpg.add_mouse_release_handler(button=dpg.mvMouseButton_Left, callback=_up)
    _chrome_centre(vw + px(30), vh + px(150))
    _draw()


def _chrome_centre(w, h):
    """The window in the middle of the studio (w and h already in screen pixels)."""
    vw, vh = dpg.get_viewport_client_width(), dpg.get_viewport_client_height()
    dpg.set_item_pos(TAG, [max(0, (vw - w) // 2), max(0, (vh - h) // 2)])


def _mouse():
    """The mouse on the picture, in its pixels, kept inside it."""
    mx, my = dpg.get_mouse_pos(local=False)
    x0, y0 = dpg.get_item_rect_min("screen_area_draw")
    vw, vh = dpg.get_item_rect_size("screen_area_draw")
    return max(0.0, min(vw, mx - x0)), max(0.0, min(vh, my - y0))


def _down(s, a):
    if not dpg.does_item_exist("screen_area_draw") or not dpg.is_item_hovered("screen_area_draw"):
        return
    x, y = _mouse()
    _ST["drag"] = (x, y)
    _ST["box"] = (x, y, x, y)
    _draw()


def _move(s, a):
    if _ST.get("drag") is None or not dpg.does_item_exist("screen_area_draw"):
        return
    x, y = _mouse()
    _ST["box"] = _ST["drag"] + (x, y)
    _draw()


def _up(s, a):
    if _ST.get("drag") is None:
        return
    _ST["drag"] = None
    l, t, r, b = _ST["box"]
    if abs(r - l) < 4 or abs(b - t) < 4:                      # a click, not a drag: the box round the click
        k = 40
        _ST["box"] = (max(0, l - k), max(0, t - k), l + k, t + k)
    _draw()


def _typed():
    try:
        area = tuple(int(dpg.get_value(f"screen_area_{k}")) for k in "xywh")
    except (TypeError, ValueError):
        return
    if area[2] >= 2 and area[3] >= 2:
        _ST["box"] = area_to_box(area, _ST["scale"], _ST["origin"])
        _draw(typed=True)


def _draw(typed=False):
    if not dpg.does_item_exist("screen_area_draw"):
        return
    c = _c()
    dpg.delete_item("screen_area_draw", children_only=True)
    vw, vh = dpg.get_item_configuration("screen_area_draw")["width"], dpg.get_item_configuration("screen_area_draw")["height"]
    dpg.draw_image(_ST["tex"], (0, 0), (vw, vh), parent="screen_area_draw")
    l, t, r, b = _ST["box"]
    l, r = sorted((l, r))
    t, b = sorted((t, b))
    shade = (0, 0, 0, 140)
    for p0, p1 in (((0, 0), (vw, t)), ((0, b), (vw, vh)), ((0, t), (l, b)), ((r, t), (vw, b))):
        if p1[0] > p0[0] and p1[1] > p0[1]:
            dpg.draw_rectangle(p0, p1, fill=shade, color=(0, 0, 0, 0), parent="screen_area_draw")
    acc = tuple(c.ACCENT[:3]) + (255,)
    dpg.draw_rectangle((l, t), (r, b), color=acc, thickness=2, parent="screen_area_draw")
    x, y, w, h = box_to_area(_ST["box"], _ST["scale"], _ST["origin"])
    if not typed:
        for k, v in zip("xywh", (x, y, w, h)):
            dpg.set_value(f"screen_area_{k}", v)
    dpg.set_value("screen_area_words", f"{w} x {h} pixels")


def _use():
    x, y, w, h = box_to_area(_ST["box"], _ST["scale"], _ST["origin"])
    cb = _ST.get("on_pick")
    _close()
    if cb:
        cb(video.area_name(x, y, w, h))


def _close(*_):
    if dpg.does_item_exist("screen_area_mouse"):
        dpg.delete_item("screen_area_mouse")
    if dpg.does_item_exist(TAG):
        dpg.delete_item(TAG)
    tex = _ST.get("tex")
    if tex and dpg.does_item_exist(tex):
        dpg.delete_item(tex)
    _ST.clear()
# AI: end
